B.YO=new A.aT("Kamera g\xf6r\xfcnt\xfcs\xfc kaydedilmez; yaln\u0131zca cihaz \xfczerinde anl\u0131k i\u015flenir.",null,B.np,B.bU,null,null,null,null,null)
B.YP=new A.aT("Profil",null,null,null,null,null,null,null,null)
B.YQ=new A.aT("BiyoOdak \xb7 Gece Ekran Maruziyeti ve Temass\u0131z Biyometrik Karar Destek Sistemi\nT\xdcB\u0130TAK 2204-A Lise \xd6\u011frencileri Ara\u015ft\u0131rma Projeleri\n\nAra\u015ft\u0131rma prototipidir. Sistem t\u0131bbi tan\u0131 koyma amac\u0131 ta\u015f\u0131maz; \xe7\u0131kt\u0131lar profesyonel t\u0131bbi de\u011ferlendirmenin yerine ge\xe7mez.",null,null,null,null,null,null,null,null)
B.YR=new A.aT("G\xfcn\xfcn \xf6nerisi",null,B.cc,null,null,null,null,null,null)
B.YS=new A.aT("Bu uygulama \xf6n kamerayla g\xf6z k\u0131rpma (PERCLOS), temass\u0131z nab\u0131z (rPPG) ve tepki s\xfcresini \xf6l\xe7erek bili\u015fsel yorgunluk ve odaklanma durumunu renkli bir g\xf6stergeyle sunar. \xd6nerileri sana \xf6zel hale getirmek i\xe7in birka\xe7 soruyu yan\u0131tla. Bu sorular yaln\u0131zca bir kez sorulur.",null,null,null,null,null,null,null,null)
B.YU=new A.aT("Web s\xfcr\xfcm\xfcnde taray\u0131c\u0131, telefonun genel ekran s\xfcresini okuyamaz. Bu y\xfczden yaln\u0131zca uygulama a\xe7\u0131kken ge\xe7en s\xfcre say\u0131l\u0131r ve 30/45/60. dakikalarda uygulama i\xe7inde uyar\u0131 g\xf6sterilir. Telefon geneli bildirimler Android s\xfcr\xfcm\xfcnde \xe7al\u0131\u015f\u0131r. iPhone'da Ayarlar > Ekran S\xfcresi > Uygulama S\u0131n\u0131rlar\u0131 ile benzer bir uyar\u0131 kurabilirsin.",null,null,null,null,null,null,null,null)
B.YV=new A.aT("Bu i\u015flem geri al\u0131namaz.",null,null,null,null,null,null,null,null)
B.YW=new A.aT("\u0130ptal",null,null,null,null,null,null,null,null)
